"use client";

import {
    TrendingUp,
    FileCheck,
    Clock,
    ArrowUpRight,
    ArrowDownRight,
    Plus,
    Zap,
    Wallet,
    Award,
    Flame,
    Target
} from "lucide-react";
import { cn } from "@/lib/utils";
import { useSimulation } from "@/components/SimulationProvider";
import useSWR from "swr";
import { fetcher } from "@/lib/fetcher";

export default function Dashboard() {
    const { currentUser } = useSimulation();

    const { data: qCertificates } = useSWR('/api/certificates', fetcher);
    const { data: qCustomers } = useSWR('/api/customers', fetcher);

    const certCount = qCertificates?.length || 0;
    const custCount = qCustomers?.length || 0;

    const xpGoal = currentUser.level === "Bronze" ? 1000 : currentUser.level === "Prata" ? 2500 : 5000;
    const xpProgress = Math.min((currentUser.xp / xpGoal) * 100, 100);

    return (
        <div className="p-4 md:p-6 lg:p-8 space-y-8">

            {/* ── Hero ── */}
            <section className="relative overflow-hidden bg-primary/10 dark:bg-gradient-to-br dark:from-slate-900 dark:to-slate-950 rounded-none text-primary dark:text-white border border-primary/20 dark:border-none shadow-sm transition-all duration-500">
                <div className="absolute top-0 right-0 w-2/5 h-full bg-primary/5 dark:bg-white/5 blur-3xl pointer-events-none" />

                <div className="relative z-10 px-8 lg:px-12 py-10">
                    {/* Top row: badges + actions */}
                    <div className="flex flex-wrap items-center justify-between gap-4 mb-6">
                        <div className="flex items-center gap-3">
                            <span className={cn(
                                "px-3 py-1 border text-[10px] font-black uppercase tracking-widest rounded-lg",
                                currentUser.level?.toLowerCase() === 'ouro' ? "bg-amber-500/10 border-amber-500/20 text-amber-700 dark:text-amber-200" :
                                    currentUser.level?.toLowerCase() === 'prata' ? "bg-slate-500/10 border-slate-500/20 text-slate-700 dark:text-slate-200" :
                                        "bg-primary/10 dark:bg-white/15 border-primary/20 dark:border-white/20 text-primary dark:text-white"
                            )}>
                                Nível {currentUser.level}
                            </span>
                            <span className="flex items-center gap-1.5 text-amber-600 dark:text-amber-300 text-xs font-bold">
                                <Flame size={13} />
                                5 Dias de Sequência
                            </span>
                        </div>

                        <div className="flex items-center gap-2">
                            <button className="bg-primary dark:bg-white text-on-primary dark:text-primary px-5 py-2.5 rounded-none font-bold text-xs shadow-sm hover:opacity-90 transition-all flex items-center gap-1.5 active:scale-95">
                                <Plus size={15} />
                                Nova Emissão
                            </button>
                            <button className="bg-primary/10 dark:bg-white/10 border border-primary/20 dark:border-white/20 text-primary dark:text-white px-5 py-2.5 rounded-none font-bold text-xs hover:bg-primary/20 dark:hover:bg-white/20 transition-all flex items-center gap-1.5 active:scale-95">
                                <Target size={15} />
                                Metas do Mês
                            </button>
                        </div>
                    </div>

                    {/* Main content: name + xp + mini stats */}
                    <div className="grid grid-cols-1 lg:grid-cols-5 gap-6 items-end">
                        {/* Left: Name + XP bar */}
                        <div className="lg:col-span-3">
                            <h1 className="text-3xl lg:text-4xl font-black leading-none mb-5 text-slate-900 dark:text-white">
                                {currentUser.name}
                            </h1>
                            <div className="max-w-sm">
                                <div className="flex justify-between items-center mb-1.5">
                                    <p className="text-[10px] font-bold text-primary/60 dark:text-white/60 uppercase tracking-widest">
                                        Progresso para {currentUser.level?.toLowerCase() === 'bronze' ? 'Prata' : currentUser.level?.toLowerCase() === 'prata' ? 'Ouro' : 'Mestre'}
                                    </p>
                                    <p className="text-[11px] font-bold text-primary dark:text-white">
                                        {currentUser.xp} <span className="text-primary/40 dark:text-white/50">/ {xpGoal} XP</span>
                                    </p>
                                </div>
                                <div className="h-2 w-full bg-primary/10 dark:bg-white/10 rounded-full overflow-hidden">
                                    <div
                                        className="h-full bg-primary dark:bg-white/80 rounded-full transition-all duration-1000"
                                        style={{ width: `${xpProgress}%` }}
                                    />
                                </div>
                            </div>
                        </div>

                        {/* Right: Mini stat cards */}
                        <div className="lg:col-span-2 grid grid-cols-2 gap-3">
                            <div className="bg-white dark:bg-white/10 border border-primary/10 dark:border-white/10 rounded-none p-4 flex flex-col gap-2 shadow-sm dark:shadow-none">
                                <div className="size-8 rounded-none bg-amber-400/20 text-amber-600 dark:text-amber-300 flex items-center justify-center">
                                    <Award size={16} />
                                </div>
                                <p className="text-[9px] font-bold text-primary/40 dark:text-white/50 uppercase tracking-widest">Badge Ativa</p>
                                <p className="text-xs font-bold text-slate-900 dark:text-white truncate">
                                    {currentUser.equippedBadge ? `"${currentUser.equippedBadge}"` : '"Nenhum"'}
                                </p>
                            </div>
                            <div className="bg-white dark:bg-white/10 border border-primary/10 dark:border-white/10 rounded-none p-4 flex flex-col gap-2 shadow-sm dark:shadow-none">
                                <div className="size-8 rounded-none bg-emerald-400/20 text-emerald-600 dark:text-emerald-400 flex items-center justify-center">
                                    <Zap size={16} />
                                </div>
                                <p className="text-[9px] font-bold text-primary/40 dark:text-white/50 uppercase tracking-widest">Missões Hoje</p>
                                <p className="text-xs font-bold text-slate-900 dark:text-white">2 / 3 Completas</p>
                            </div>
                        </div>
                    </div>
                </div>
            </section>

            {/* ── KPI Grid ── */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                <StatCard
                    title="Vendas do Mês"
                    value={currentUser.sales_total.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                    change="+12.5%"
                    isPositive={true}
                    icon={TrendingUp}
                    color="blue"
                />
                <StatCard
                    title="Sua Wallet"
                    value={currentUser.wallet.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                    change="+R$ 45,00"
                    isPositive={true}
                    icon={Wallet}
                    color="emerald"
                />
                <StatCard
                    title="Meta de XP"
                    value={currentUser.xp.toString()}
                    change={`${Math.floor(xpProgress)}%`}
                    isPositive={true}
                    icon={Award}
                    color="amber"
                />
                <StatCard
                    title="Certificados"
                    value={certCount.toString()}
                    change={`${custCount} clientes`}
                    isPositive={true}
                    icon={FileCheck}
                    color="indigo"
                />
            </div>

            {/* ── Bottom Grid: Missions + Seals ── */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

                {/* Missions — 2/3 width */}
                <div className="lg:col-span-2 bg-[var(--card)] rounded-none border border-[var(--border)] p-6 shadow-sm">
                    <div className="flex items-center justify-between mb-5">
                        <div>
                            <h3 className="text-base font-black tracking-tight text-[var(--foreground)]">Missões Ativas</h3>
                            <p className="text-[10px] text-[var(--muted)] font-bold uppercase tracking-widest mt-0.5">Conclua para ganhar XP extra</p>
                        </div>
                        <span className="px-2 py-1 bg-primary/5 text-primary text-[10px] font-bold rounded-lg border border-primary/10">
                            1/3 Completas
                        </span>
                    </div>

                    <div className="space-y-3">
                        <MissionItem title="Venda em Sequência" desc="Realize 1 venda hoje para manter sua ofensiva de 5 dias." progress={100} xp={50} completed />
                        <MissionItem title="Especialista PJ" desc="Emita 3 certificados PJ nesta semana." progress={66} xp={150} />
                        <MissionItem title="Indicação Premiada" desc="Indique 1 contador para a plataforma." progress={0} xp={500} />
                    </div>
                </div>

                <div className="bg-[var(--card)] rounded-none border border-[var(--border)] shadow-sm flex flex-col">
                    <div className="px-5 pt-5 pb-4 border-b border-[var(--border)]">
                        <h3 className="text-[var(--foreground)] text-[11px] font-black uppercase tracking-widest flex items-center gap-2">
                            <Award className="text-primary" size={14} />
                            Selos Equipados
                        </h3>
                    </div>

                    <div className="p-4 space-y-3 flex-1">
                        {/* Active seal */}
                        <div className="p-4 rounded-none bg-primary/5 dark:bg-white/5 border border-primary/10 dark:border-white/10 flex items-center gap-3 relative hover:bg-primary/10 dark:hover:bg-white/10 transition-all cursor-pointer">
                            <div className={cn(
                                "size-10 rounded-none flex items-center justify-center shrink-0",
                                currentUser.level?.toLowerCase() === 'ouro' ? "bg-amber-400/20 text-amber-600" :
                                    currentUser.level?.toLowerCase() === 'prata' ? "bg-slate-400/20 text-slate-600" :
                                        "bg-orange-400/20 text-orange-600"
                            )}>
                                <Zap size={18} />
                            </div>
                            <div className="min-w-0">
                                <p className="text-[11px] font-bold text-slate-900 dark:text-white uppercase tracking-tight">Selo {currentUser.level}</p>
                                <p className="text-[10px] text-[var(--muted)] truncate">Benefícios de nível {currentUser.level} ativos</p>
                            </div>
                            <div className="absolute -top-1 -right-1 size-2.5 bg-emerald-400 rounded-full border-2 border-[var(--card)] dark:border-slate-900" />
                        </div>

                        {/* Empty slot */}
                        <div className="p-4 rounded-none border border-dashed border-[var(--border)] dark:border-slate-700 flex items-center gap-3 opacity-50 hover:opacity-100 transition-all cursor-pointer">
                            <div className="size-10 rounded-none bg-[var(--accent)] dark:bg-slate-800 text-[var(--muted)] flex items-center justify-center shrink-0">
                                <Award size={18} />
                            </div>
                            <div>
                                <p className="text-[11px] font-bold text-slate-900 dark:text-slate-300 uppercase tracking-tight">Vazio</p>
                                <p className="text-[10px] text-[var(--muted)]">Equipe um selo de buff</p>
                            </div>
                        </div>

                        {/* Quick stats strip */}
                        <div className="pt-3 border-t border-[var(--border)] grid grid-cols-2 gap-3">
                            <div className="text-center">
                                <p className="text-lg font-black text-slate-900 dark:text-white">{currentUser.xp.toLocaleString()}</p>
                                <p className="text-[9px] font-bold text-[var(--muted)] uppercase tracking-widest">XP Total</p>
                            </div>
                            <div className="text-center">
                                <p className="text-lg font-black text-slate-900 dark:text-white">{custCount}</p>
                                <p className="text-[9px] font-bold text-[var(--muted)] uppercase tracking-widest">Clientes</p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

function MissionItem({ title, desc, progress, xp, completed }: any) {
    return (
        <div className={cn(
            "px-4 py-3.5 rounded-none border transition-all flex items-center gap-4",
            completed
                ? "bg-emerald-500/5 border-emerald-500/15 dark:border-emerald-500/20"
                : "bg-[var(--accent)]/30 border-[var(--border)] hover:border-primary/20"
        )}>
            <div className={cn(
                "size-9 rounded-none flex items-center justify-center shrink-0",
                completed ? "bg-emerald-500/15 text-emerald-600 dark:text-emerald-400" : "bg-[var(--accent)] text-[var(--muted)]"
            )}>
                {completed ? <FileCheck size={16} /> : <Clock size={16} />}
            </div>
            <div className="flex-1 min-w-0">
                <div className="flex justify-between items-center mb-1">
                    <p className="font-bold text-sm tracking-tight text-[var(--foreground)] truncate">{title}</p>
                    <p className="text-[10px] font-bold text-primary uppercase shrink-0 ml-2">+{xp} XP</p>
                </div>
                <p className="text-[11px] text-[var(--muted)] mb-2 leading-snug">{desc}</p>
                <div className="h-1 w-full bg-[var(--border)] rounded-full overflow-hidden">
                    <div
                        className={cn("h-full rounded-full transition-all duration-700", completed ? "bg-emerald-500" : "bg-primary")}
                        style={{ width: `${progress}%` }}
                    />
                </div>
            </div>
        </div>
    );
}

function StatCard({ title, value, change, isPositive, icon: Icon, color }: any) {
    const colorMap: any = {
        blue: { bg: "bg-blue-500/10", text: "text-blue-600 dark:text-blue-400" },
        emerald: { bg: "bg-emerald-500/10", text: "text-emerald-600 dark:text-emerald-400" },
        amber: { bg: "bg-amber-500/10", text: "text-amber-600 dark:text-amber-400" },
        indigo: { bg: "bg-indigo-500/10", text: "text-indigo-600 dark:text-indigo-400" },
    };
    const c = colorMap[color];

    return (
        <div className="bg-[var(--card)] rounded-none border border-[var(--border)] p-5 shadow-sm hover:shadow-md transition-shadow">
            <div className="flex items-center justify-between mb-4">
                <div className={cn("size-9 rounded-none flex items-center justify-center", c.bg, c.text)}>
                    <Icon size={17} />
                </div>
                <div className={cn(
                    "flex items-center gap-1 px-2 py-0.5 rounded-md text-[10px] font-bold",
                    isPositive
                        ? "bg-emerald-50 text-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400"
                        : "bg-rose-50 text-rose-700 dark:bg-rose-900/20 dark:text-rose-400"
                )}>
                    {isPositive ? <ArrowUpRight size={11} /> : <ArrowDownRight size={11} />}
                    {change}
                </div>
            </div>
            <p className="text-[10px] font-bold text-[var(--muted)] uppercase tracking-widest mb-1">{title}</p>
            <h4 className="text-2xl font-black text-[var(--foreground)]">{value}</h4>
        </div>
    );
}
